import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import BookingForm from "../components/BookingForm";
import BookingList from "../components/BookingList";
import InchargeModal from "../components/InchargeModal";
import Navbar from "../components/Navbar";
import RejectModal from "../components/RejectModal";
import Sidebar from "../components/Sidebar";
import { useAppContext } from "../context/AppContext";
import api from "../services/api";
import { formatAxiosError, formatErrorMessage } from "../utils/errorMessages";

const clientNavItems = [
  { key: "overview", label: "Overview", icon: "O", to: "/" },
  { key: "new-booking", label: "New Booking", icon: "+", to: "/new-booking" },
  { key: "my-bookings", label: "My Bookings", icon: "B", to: "/my-bookings" },
  { key: "incharges", label: "Incharges", icon: "I" }
];

const pageContent = {
  overview: {
    title: "Booking Overview",
    subtitle: "Track recent requests, approvals, and rejections in one place."
  },
  "new-booking": {
    title: "New Booking",
    subtitle: "Select a block or extra center and submit a booking request."
  },
  "my-bookings": {
    title: "My Bookings",
    subtitle: "Review your requests, rejection notes, and cancellations."
  }
};

const initialFormState = {
  resourceScope: "block",
  blockId: "",
  resourceId: "",
  name: "",
  department: "",
  bookingDate: "",
  startTime: "",
  endTime: "",
  purpose: ""
};

const initialStats = {
  total: 0,
  pending: 0,
  approved: 0,
  rejected: 0
};

const SkeletonLoader = () => (
  <div className="stats-grid skeleton-stats" aria-label="Loading dashboard">
    <div className="skeleton-card" />
    <div className="skeleton-card" />
    <div className="skeleton-card" />
    <div className="skeleton-card" />
  </div>
);

const ClientDashboard = ({ view = "overview" }) => {
  const navigate = useNavigate();
  const { incharges, fetchInitialData, prefetching } = useAppContext();
  const [bookings, setBookings] = useState([]);
  const [stats, setStats] = useState(initialStats);
  const [error, setError] = useState("");
  const [showIncharges, setShowIncharges] = useState(false);
  const [formData, setFormData] = useState(initialFormState);
  const [message, setMessage] = useState("");
  const [availabilityMsg, setAvailabilityMsg] = useState("");
  const [formLoading, setFormLoading] = useState(false);
  const [loading, setLoading] = useState(true);
  const [cancelBookingId, setCancelBookingId] = useState(null);
  const [cancelLoading, setCancelLoading] = useState(false);
  const [refreshing, setRefreshing] = useState(false);

  const handleLogout = useCallback(() => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    navigate("/login");
  }, [navigate]);

  const loadBookings = useCallback(async () => {
    try {
      const response = await api.get("/client/bookings");
      setBookings(response.data || []);
      localStorage.setItem("bookings", JSON.stringify(response.data || []));
    } catch (error) {
      setMessage(formatErrorMessage(error.response?.data?.detail, "Could not load bookings."));
    }
  }, []);

  const fetchDashboard = useCallback(async (options = {}) => {
    const force = Boolean(options.force);
    setLoading(true);
    setError("");

    const cached = localStorage.getItem("dashboard");
    if (cached) {
      try {
        setStats(JSON.parse(cached));
      } catch (err) {
        localStorage.removeItem("dashboard");
      }
    }

    const cachedBookings = localStorage.getItem("bookings");
    if (cachedBookings) {
      try {
        setBookings(JSON.parse(cachedBookings));
      } catch (err) {
        localStorage.removeItem("bookings");
      }
    }

    try {
      const [dashboard, bookings] = await Promise.all([
        api.get("/client/dashboard", { cache: !force }),
        api.get("/client/bookings", { cache: !force }),
        fetchInitialData({ force })
      ]);

      setStats(dashboard.data || initialStats);
      setBookings(bookings.data || []);
      localStorage.setItem("dashboard", JSON.stringify(dashboard.data || initialStats));
      localStorage.setItem("bookings", JSON.stringify(bookings.data || []));
    } catch (err) {
      setError("Something went wrong");
    } finally {
      setLoading(false);
    }
  }, [fetchInitialData]);

  useEffect(() => {
    fetchDashboard();
  }, [fetchDashboard]);

  const handleRefresh = useCallback(async () => {
    setRefreshing(true);
    api.clearCache(["/client/dashboard", "/client/bookings", "/blocks", "/incharges", "/all-resources"]);
    try {
      await fetchDashboard({ force: true });
    } finally {
      setRefreshing(false);
    }
  }, [fetchDashboard]);

  const handleChange = useCallback((event) => {
    const { name, value } = event.target;
    setAvailabilityMsg("");
    setFormData((previous) => ({
      ...previous,
      [name]: value
    }));
  }, []);

  const handleAvailabilityCheck = useCallback(async () => {
    setAvailabilityMsg("");

    try {
      const res = await api.post("/client/availability", {
        resource_id: Number(formData.resourceId),
        booking_date: formData.bookingDate,
        start_time: formData.startTime,
        end_time: formData.endTime
      });

      setAvailabilityMsg(res.data.message || (res.data.available ? "Available" : "Not available"));
    } catch (err) {
      const errorData = err.response?.data?.detail;

      if (Array.isArray(errorData)) {
        setAvailabilityMsg(errorData.map((e) => e.msg).filter(Boolean).join(", ") || "Error occurred");
      } else if (typeof errorData === "object") {
        setAvailabilityMsg(errorData?.msg || "Error occurred");
      } else {
        setAvailabilityMsg(errorData || formatAxiosError(err, "Not available"));
      }
    }
  }, [formData.bookingDate, formData.endTime, formData.resourceId, formData.startTime]);

  const handleSubmit = useCallback(async (event) => {
    event.preventDefault();
    setFormLoading(true);
    setMessage("");
    setAvailabilityMsg("");
    const optimisticBooking = {
      id: `temp-${Date.now()}`,
      resource_id: Number(formData.resourceId),
      name: formData.name,
      department: formData.department,
      booking_date: formData.bookingDate,
      start_time: formData.startTime,
      end_time: formData.endTime,
      purpose: formData.purpose,
      status: "pending"
    };
    const previousBookings = bookings;
    const previousStats = stats;
    setBookings((current) => [optimisticBooking, ...current]);
    setStats((current) => ({
      ...current,
      total: current.total + 1,
      pending: current.pending + 1
    }));

    try {
      await api.post("/client/bookings", {
        resource_id: Number(formData.resourceId),
        name: formData.name,
        department: formData.department,
        booking_date: formData.bookingDate,
        start_time: formData.startTime,
        end_time: formData.endTime,
        purpose: formData.purpose
      });

      setMessage("Booking created successfully.");
      setFormData(initialFormState);
      localStorage.removeItem("dashboard");
      localStorage.removeItem("bookings");
      await fetchDashboard();
      navigate("/my-bookings");
    } catch (error) {
      setBookings(previousBookings);
      setStats(previousStats);
      setMessage(formatErrorMessage(error.response?.data?.detail, "Something went wrong"));
    } finally {
      setFormLoading(false);
    }
  }, [bookings, fetchDashboard, formData, navigate, stats]);

  const handleCancel = useCallback((bookingId) => {
    setCancelBookingId(bookingId);
  }, []);

  const closeCancelModal = useCallback(() => {
    if (!cancelLoading) {
      setCancelBookingId(null);
    }
  }, [cancelLoading]);

  const handleCancelSubmit = useCallback(async (reason) => {
    if (!cancelBookingId) {
      return;
    }

    setCancelLoading(true);
    const previousBookings = bookings;
    setBookings((current) =>
      current.map((booking) =>
        booking.id === cancelBookingId
          ? { ...booking, status: "cancelled", cancellation_reason: reason }
          : booking
      )
    );
    try {
      await api.post(`/client/bookings/${cancelBookingId}/cancel`, { reason });
      setMessage("Booking cancelled.");
      setCancelBookingId(null);
      localStorage.removeItem("dashboard");
      localStorage.removeItem("bookings");
      await fetchDashboard();
    } catch (error) {
      setBookings(previousBookings);
      setMessage(formatErrorMessage(error.response?.data?.detail, "Something went wrong"));
    } finally {
      setCancelLoading(false);
    }
  }, [bookings, cancelBookingId, fetchDashboard]);

  const handleSidebarSelect = useCallback((itemKey) => {
    if (itemKey === "incharges") {
      setShowIncharges(true);
    }
  }, []);

  const currentPage = pageContent[view] || pageContent.overview;
  const recentBookings = useMemo(() => bookings.slice(0, 3), [bookings]);

  return (
    <div className="dashboard-shell">
      <Sidebar
        role="Client"
        items={clientNavItems}
        activeItem={showIncharges ? "incharges" : undefined}
        onSelect={handleSidebarSelect}
        onLogout={handleLogout}
      />

      <main className="dashboard-main">
        <Navbar title={currentPage.title} subtitle={currentPage.subtitle} userRole="Client" onRefresh={handleRefresh} refreshing={refreshing} />

        {error ? (
          <div className="error-box">
            Something went wrong. <button type="button" onClick={handleRefresh}>Retry</button>
          </div>
        ) : null}

        {message ? (
          <div className="alert info alert-box">{String(message)}</div>
        ) : null}

        {view === "overview" ? (
          <>
            {loading || prefetching ? (
              <SkeletonLoader />
            ) : (
              <>
                <section className="stats-grid">
                  <div className="card total">
                    <p>Total</p>
                    <h2>{stats.total}</h2>
                  </div>
                  <div className="card pending">
                    <p>Pending</p>
                    <h2>{stats.pending}</h2>
                  </div>
                  <div className="card approved">
                    <p>Approved</p>
                    <h2>{stats.approved}</h2>
                  </div>
                  <div className="card rejected">
                    <p>Rejected</p>
                    <h2>{stats.rejected}</h2>
                  </div>
                </section>

                <BookingList
                  title="Recent Bookings"
                  description="Your latest requests and outcomes."
                  bookings={recentBookings}
                />
              </>
            )}
          </>
        ) : null}

        {view === "new-booking" ? (
          <BookingForm
            formData={formData}
            onChange={handleChange}
            onSubmit={handleSubmit}
            onAvailabilityCheck={handleAvailabilityCheck}
            availabilityMsg={availabilityMsg}
            loading={formLoading}
          />
        ) : null}

        {view === "my-bookings" ? (
          <BookingList
            title="My Bookings"
            description="Rejected requests include the saved reason."
            bookings={bookings}
            onCancel={handleCancel}
            showActions
          />
        ) : null}
      </main>

      <InchargeModal open={showIncharges} groups={incharges} onClose={() => setShowIncharges(false)} />
      <RejectModal
        open={Boolean(cancelBookingId)}
        loading={cancelLoading}
        onClose={closeCancelModal}
        onSubmit={handleCancelSubmit}
      />
    </div>
  );
};

export default ClientDashboard;
